
const $=id=>document.getElementById(id);
const NAMES=['Sinal 1 – PGM','Sinal 2 – Clean Feed','Sinal 3 – ISO 1','Sinal 4 – Externo (RTMP)'];
const FEEDS=['RTMP','SRT','SDI (DeckLink)','RTMP'];
const THUMBS=["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"];
const ICONS=['▣','▣','▣','▣'];
const rawRecords=(()=>{try{return JSON.parse(localStorage.getItem('ingest-prototype-records')||'[]')}catch(e){return []}})();
let records=!window.ingestLocal&&Array.isArray(rawRecords)?rawRecords:[];
let recording=window.ingestLocal?[false,false,false,false]:[true,true,false,false]; // Visual demonstration, never a real REC.
let filter='all', period='day', selectedDate=localDate(new Date()), currentPage='dashboard', channelAlert=[false,false,false,false], toastTimer;
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function escapeHTML(t){return String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500)}
function openModal(title,content,isHTML=false){$('modal-title').textContent=title;if(isHTML)$('modal-text').innerHTML=content;else $('modal-text').textContent=content;$('modal').classList.add('show')}
function closeModal(){$('modal').classList.remove('show')}
function showNotice(){openModal('Estado do Ingest Control','Esta é uma demonstração do layout. O motor RTMP/SRT/SDI, a gravação real, o armazenamento e as notificações ainda não estão conectados. Os botões REC apenas simulam o estado na interface.')}
const pages=['dashboard','operation','signals','agenda','list','recordings','files','reports','settings'];
function view(page){if(!pages.includes(page))return;currentPage=page;pages.forEach(p=>{$('page-'+p)?.classList.toggle('hidden',page!==p);$('nav-'+p)?.classList.toggle('active',page===p)});render();window.scrollTo({top:0,behavior:'instant'})}
function channelCard(i){
 if(i>1)return `<article class="channel local-channel"><div class="channel-head"><strong>${escapeHTML(NAMES[i])}</strong></div><div class="channel-meter"><span class="rec-state">Não integrado</span></div><div class="channel-controls"><small>Fora do piloto</small></div></article>`;
 const rec=recording[i],name=NAMES[i],status=rec?'<span class="rec-state recording"><span class="rec-dot"></span>REC · SIMULAÇÃO</span>':'<span class="rec-state"><span class="rec-dot"></span>Standby</span>';return `<article class="channel"><div class="channel-head"><strong><span class="signal-dot"></span>${escapeHTML(name)}</strong><span class="signal">ILUSTRATIVO</span></div><div class="video"><img loading="lazy" src="${THUMBS[i]}" alt="Imagem ilustrativa de ${escapeHTML(name)}"><div class="preview-tag">Sem sinal real conectado</div></div><div class="channel-controls">${status}<div class="channel-btns"><button class="mini-control" onclick="toggleRecord(${i})" title="${rec?'Parar':'Iniciar'} gravação simulada">${rec?'■':'▶'}</button><button class="mini-control" onclick="channelDetails(${i})" title="Detalhes do canal">⚙</button></div></div></article>`}
function renderChannels(){const indices=NAMES.map((_,i)=>i).filter(i=>filter==='all'||filter==='rec'&&recording[i]||filter==='idle'&&!recording[i]||filter==='alert'&&channelAlert[i]);const h=indices.length?indices.map(channelCard).join(''):'<div class="empty" style="grid-column:1/-1">Nenhum canal encontrado para este filtro.</div>';$('dashboard-channels').innerHTML=h;$('operation-channels').innerHTML=NAMES.map((_,i)=>channelCard(i)).join('');$('signals-channels').innerHTML=NAMES.map((_,i)=>channelCard(i)).join('');document.querySelector('[data-filter="rec"]').textContent=`Gravando (${recording.filter(Boolean).length})`;document.querySelector('[data-filter="idle"]').textContent=`Standby (${recording.filter(x=>!x).length})`;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('on',b.dataset.filter===filter));$('stat-rec').textContent=recording.filter(Boolean).length;}
function setFilter(f){filter=f;renderChannels()}
function toggleRecord(i){if(i>1)return;recording[i]=!recording[i];renderChannels();toast(`${NAMES[i]}: ${recording[i]?'REC':'parado'} apenas na simulação — nenhum arquivo será gravado.`)}
function recordAll(){recording=recording.map((_,i)=>i<2);renderChannels();toast('REC ALL ativado apenas no protótipo. Nenhum sinal real está sendo gravado.')}
function stopAll(){recording=recording.map(()=>false);renderChannels();toast('Todos os indicadores REC foram interrompidos na simulação.')}
function chooseRecord(){openModal('Gravar Agora · demonstração',`<p>Selecione o canal para alterar o indicador REC. Esta ação <b>não inicia gravação real.</b></p><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:15px">${NAMES.slice(0,2).map((n,i)=>`<button class="btn" onclick="closeModal();toggleRecord(${i})">● ${escapeHTML(n)}</button>`).join('')}</div>`,true)}
function channelDetails(i){openModal(NAMES[i],`Protocolo previsto: ${FEEDS[i]}\nEstado visual: ${recording[i]?'REC simulado':'standby'}\nFonte de vídeo: imagem ilustrativa\nConexão ao motor de gravação: pendente\n\nPara habilitar preview e captura reais será necessária a integração com um servidor de ingest.`)}
function setTheme(t){if(!['rural','light','dark'].includes(t))t='rural';document.body.classList.remove('rural','light','dark');document.body.classList.add(t);try{localStorage.setItem('ingest-theme',t)}catch(e){};$('theme-select').value=t}
function cycleTheme(){const a=['rural','light','dark'],v=a[(a.indexOf(document.body.classList.contains('dark')?'dark':document.body.classList.contains('light')?'light':'rural')+1)%3];setTheme(v);toast('Tema alterado: '+({rural:'Canal Rural · azul-marinho',light:'Claro',dark:'Escuro'}[v]))}
const samples=[{program:'Mercado & Companhia',date:localDate(new Date()),start:'09:00',end:'11:00',channel:0,demo:true},{program:'Giro do Boi',date:localDate(new Date()),start:'11:00',end:'13:00',channel:1,demo:true},{program:'Planeta Campo',date:localDate(new Date()),start:'14:00',end:'16:00',channel:2,demo:true},{program:'Especial Rural',date:localDate(new Date()),start:'16:30',end:'18:00',channel:3,demo:true}];
function channelOf(r){const v=r['input-device']||r['signal-name']||'';const m=String(v).match(/(?:Canal|CH)\s*([1-4])/i);if(m)return Number(m[1])-1;const f=String(r.feed||'');if(f.includes('ISO'))return 2;if(f.includes('Clean'))return 1;if(f.includes('externo')||f.includes('Retorno'))return 3;return 0}
function schedEvents(){return window.ingestLocal?records.map((r,i)=>({...r,index:i,demo:false})):records.length?records.map((r,i)=>({...r,channel:channelOf(r),index:i,demo:false})):samples}
function minute(t){const [h,m]=String(t||'00:00').split(':').map(Number);return h*60+m}
function onDay(r,day){return r.date===day}
function formatDate(day){const d=new Date(day+'T12:00:00');return d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})}
function eventDetails(r){if(r.demo){openModal('Exemplo de programação',`${r.program}\n${formatDate(r.date)} · ${r.start}–${r.end}\n${NAMES[r.channel]}\n\nEste agendamento é somente um exemplo visual; não está salvo nem será executado.`)}else details(r.index)}
function renderTimeline(){if(!$('timeline-date'))return;$('timeline-date').value=selectedDate;['day','week','month'].forEach(p=>$('tab-'+p).classList.toggle('active',period===p));let ev=schedEvents();if(period!=='day'){const day=new Date(selectedDate+'T12:00:00');let end=new Date(day);end.setDate(day.getDate()+(period==='week'?7:31));const shown=ev.filter(r=>r.date>=localDate(day)&&r.date<localDate(end));$('timeline-container').innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Programa / Evento</th><th>Sinal</th><th>Horário</th><th>Tipo</th></tr></thead><tbody>${shown.length?shown.map(r=>`<tr><td>${escapeHTML(formatDate(r.date))}</td><td><button class="text-link" onclick="eventFromUI(${r.demo?'true':'false'},${r.demo?samples.indexOf(r):r.index})">${escapeHTML(r.program)}</button></td><td>${escapeHTML(r.source_name||NAMES[r.channel])}</td><td>${escapeHTML(r.start)}–${escapeHTML(r.end)}</td><td><span class="badge ${r.demo?'demo':''}">${r.demo?'Exemplo':'Salvo'}</span></td></tr>`).join(''):'<tr><td colspan="5" class="empty">Nenhum agendamento neste período.</td></tr>'}</tbody></table></div>`;return}
 const firstHour=window.ingestLocal?0:7,hourCount=window.ingestLocal?24:14;
 const hours=Array.from({length:hourCount},(_,i)=>i+firstHour),rowNames=['Sinal 1 – PGM','Sinal 2 – Clean Feed','Sinal 3 – ISO 1','Sinal 4 – Externo'];let head=`<div class="time-head"><div>Sinal</div>${hours.map(h=>`<div>${String(h).padStart(2,'0')}:00</div>`).join('')}</div>`;
 const todayNow=new Date(),today=localDate(todayNow),nowMin=todayNow.getHours()*60+todayNow.getMinutes();
 let rows=rowNames.map((n,i)=>{const rects=ev.filter(r=>r.channel===i&&(r.endDate?r.date<=selectedDate&&r.endDate>=selectedDate:onDay(r,selectedDate))).map(r=>{let start=r.date<selectedDate?0:minute(r.start),end=r.endDate>selectedDate?1440:minute(r.end),a=Math.max(0,(start-firstHour*60)/(hourCount*60)),b=Math.min(1,(end-firstHour*60)/(hourCount*60));if(b<=a)return '';const label=escapeHTML(r.program||'Gravação'),index=r.demo?samples.indexOf(r):r.index;return `<div class="time-event e${i%4}" style="left:${(a*100).toFixed(3)}%;width:${((b-a)*100).toFixed(3)}%" title="${label} ${escapeHTML(r.start)}–${escapeHTML(r.end)}" onclick="eventFromUI(${r.demo?'true':'false'},${index})">${label}<span>${escapeHTML(r.start)}–${escapeHTML(r.end)}</span></div>`}).join('');const now=(selectedDate===today&&nowMin>=firstHour*60&&nowMin<(firstHour+hourCount)*60)?`<div class="time-now" style="left:${((nowMin-firstHour*60)/(hourCount*60)*100).toFixed(3)}%"></div>`:'';return `<div class="time-row"><div class="label-cell">${n}</div>${hours.map(()=>'<div class="hour-cell"></div>').join('')}<div class="time-bars">${rects}${now}</div></div>`}).join('');$('timeline-container').innerHTML=`<div class="timeline-scroll"><div class="time-chart" style="--timeline-hours:${hourCount}">${head}${rows}</div></div><div class="minor-note">${window.ingestLocal?'Agenda do agente local. Consulte Agendamentos para ver o histórico completo.':records.length?'Agenda montada a partir dos registros deste navegador.':'Eventos coloridos são apenas exemplos visuais. Crie um agendamento para exibir seus dados.'}</div>`}
function eventFromUI(demo,i){if(demo)eventDetails(samples[i]);else details(i)}
function selectDay(t){if(t)selectedDate=t;renderTimeline()}
function shiftDay(d){const x=new Date(selectedDate+'T12:00:00');x.setDate(x.getDate()+d*(period==='month'?30:period==='week'?7:1));selectedDate=localDate(x);renderTimeline()}
function setPeriod(p){period=p;renderTimeline()}
function renderRecent(){const rows=samples.map((r,i)=>`<tr><td><img class="recent-illustration" src="${THUMBS[i]}" alt=""><b>${escapeHTML(r.program)}</b><small>${escapeHTML(NAMES[i])}</small></td><td>${escapeHTML(formatDate(r.date))}</td><td><span class="badge demo">Exemplo</span></td><td class="action-cell"><button class="table-btn" onclick="eventDetails(samples[${i}])" title="Detalhes do exemplo">⋯</button></td></tr>`).join('');const t=`<div class="table-wrap"><table class="data-table"><thead><tr><th>Programa / Sinal</th><th>Data</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows}</tbody></table></div><div class="minor-note">Exemplos de apresentação. Nenhum arquivo foi gravado ou disponibilizado para download.</div>`;$('recent-recordings').innerHTML=t;$('all-recordings').innerHTML=t}
function renderRecords(){const el=$('records');el.innerHTML=records.length?records.map((r,i)=>`<tr><td><b>${escapeHTML(r.program)}</b></td><td>${escapeHTML(r.date)}</td><td>${escapeHTML(r.start)}–${escapeHTML(r.end)}</td><td>${escapeHTML(r['signal-name']||r.protocol||'—')}</td><td>${escapeHTML(r.format||'—')}</td><td><span class="pill">Salvo · demo</span></td><td><button class="btn small" onclick="details(${i})">Detalhes</button> <button class="btn small" onclick="removeRecord(${i})">Excluir</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">Nenhum agendamento salvo. Clique em Novo agendamento para começar.</td></tr>';$('stat-agenda').textContent=records.length;$('reports-count').textContent=records.length;}
function details(i){const r=records[i];if(!r)return;openModal(r.program||'Agendamento',Object.entries(r).filter(([key])=>key!=='signal-url').map(([key,value])=>`${key}: ${value}`).join('\n')+'\n\nDados salvos apenas neste navegador. Gravação não executada.')}
function removeRecord(i){const r=records[i];if(!r)return;if(confirm(`Excluir o agendamento de ${r.program}?`)){records.splice(i,1);store();render();toast('Agendamento excluído deste navegador.')}}
function store(){try{localStorage.setItem('ingest-prototype-records',JSON.stringify(records))}catch(e){alert('Não foi possível salvar no armazenamento local.')}}
function exportJSON(){const blob=new Blob([JSON.stringify(records,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='agendamentos-ingest.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function render(){renderChannels();renderTimeline();renderRecent();renderRecords()}
function setupForm(){const form=$('schedule-form');form.addEventListener('submit',e=>{e.preventDefault();if(window.ingestLocal)return window.submitLocalSchedule();if($('end').value<=$('start').value){alert('O término deve ser posterior ao início.');return}const rec={};form.querySelectorAll('input,select,textarea').forEach(el=>{if(el.id)rec[el.id]=el.type==='checkbox'?el.checked:el.value});delete rec['signal-url'];records.push(rec);store();form.reset();$('protocol').value='RTMP';document.querySelectorAll('#signal-chips .chip').forEach(b=>b.classList.toggle('on',b.dataset.val==='RTMP'));$('urlwrap').classList.remove('hidden');$('date').value=localDate(new Date());selectedDate=rec.date;view('list');toast('Agendamento salvo localmente. Nenhuma gravação real foi programada no servidor.');});document.querySelectorAll('#signal-chips .chip').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#signal-chips .chip').forEach(x=>x.classList.remove('on'));b.classList.add('on');$('protocol').value=b.dataset.val;$('urlwrap').classList.toggle('hidden',['SDI','NDI','Arquivo'].includes(b.dataset.val))}));$('date').value=localDate(new Date())}
function setupSearch(){$('global-search').addEventListener('keydown',e=>{if(e.key!=='Enter')return;const q=e.target.value.trim().toLowerCase();if(!q)return;let i=records.findIndex(r=>(r.program||'').toLowerCase().includes(q));if(i>=0){view('list');details(i);return}if(q.includes('agenda')||q.includes('program'))view('list');else if(q.includes('grava'))view('recordings');else if(q.includes('sinal')||q.includes('canal'))view('signals');else if(q.includes('arquivo'))view('files');else toast('Nenhum registro local corresponde a essa busca.')})}
setTheme((()=>{try{return localStorage.getItem('ingest-theme')}catch(e){return 'rural'}})()||'rural');setupForm();setupSearch();if(!window.ingestLocal)view('dashboard');



try { const d=new Date();const e=document.getElementById('dash-today'); if(e) e.textContent=new Intl.DateTimeFormat('pt-BR',{weekday:'short',day:'2-digit',month:'short',year:'numeric'}).format(d).replace(/\./g,'').toUpperCase(); } catch(e){}

